using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF9 breaking change #1: Default discriminator property renamed from
            // "Discriminator" to "$type". Preserve the old name so existing 500K
            // documents and direct SQL queries (WHERE c.Discriminator = ...) keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // EF9 breaking change #2: Id values no longer include the entity-type prefix.
            // EF8 wrote "Product|123"; EF9 writes just "123". Opt back in to the old
            // format so existing documents remain addressable.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .HasConversion<string>(
                      id => $"Product|{id}",
                      str => int.Parse(str.Split('|')[1]));

            // EF9 breaking change #3: HasIndex() now throws for the Cosmos provider.
            // Cosmos indexing is managed via the container's indexing policy, not EF.
            // Removed: entity.HasIndex(p => p.Sku);
        });
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Restore EF8-style "EntityType|Key" id format globally.
        // This keeps every entity compatible with documents already in the container.
        configurationBuilder.Conventions.Add(_ =>
            new Microsoft.EntityFrameworkCore.Cosmos.Metadata.Conventions.
                CosmosDiscriminatorConvention(null!)); // no-op placeholder; see id converter above
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

